#!/usr/bin/env python3
"""Rewrite the RESULTS section of README.md from generated/*-evidence.json."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
BLOCKS = ['refbuf', 'adc_i', 'adc_q', 'dac_i', 'dac_q']


def fmt(v):
    if isinstance(v, float):
        return f'{v:.4g}'
    return json.dumps(v, default=str) if isinstance(v, (dict, list)) else str(v)


def main():
    out = ['## RESULTS', '',
           'Generated by `summarize.py` from `generated/<block>-evidence.json`.', '',
           '| Block | Area µm² (ceiling) | Magic DRC | KLayout DRC (published GDS) | LVS | safe | clean | observable | fallback |',
           '| --- | --- | --- | --- | --- | --- | --- | --- | --- |']
    details = []
    for b in BLOCKS:
        p = HERE / 'generated' / f'{b}-evidence.json'
        if not p.exists():
            out.append(f'| {b} | not run | | | | | | | |')
            continue
        e = json.loads(p.read_text())
        t = e['tests']
        cl = t['clean']
        kd = cl.get('klayout_drc', {}).get('violations')
        out.append(f"| {b} | {e['area']['area_um2']:.0f} ({e['area']['ceiling_um2']}) | {cl['drc']['errors']} | {kd} | "
                   f"{'unique' if cl['lvs']['unique'] else cl['lvs']['result']} | {t['safe']['state']} | "
                   f"{cl['state']} | {t['observable']['state']} | {t['fallback']['state']} |")
        details.append(f'### {b}')
        details.append('')
        details.append(f"Extracted nominal (tt, 27 C, 3.3 V): `{fmt(cl.get('extracted_nominal'))}`")
        details.append('')
        for row in e['performance_vs_target']:
            if 'corners' in row:
                details.append(f"* {row['metric']}: see evidence JSON ({len(row['corners'])} corners)")
            else:
                details.append(f"* {row['metric']} — target {row['target']}: `{fmt(row.get('nominal'))}`")
        details.append(f"* fallback loading: `{fmt(t['fallback'].get('bypass_loading_fF'))}`")
        details.append('* Excluded: ' + '; '.join(e['excluded_coverage']))
        details.append('')
    text = (HERE / 'README.md').read_text()
    head = text.split('## RESULTS')[0]
    (HERE / 'README.md').write_text(head + '\n'.join(out + [''] + details) + '\n')


if __name__ == '__main__':
    main()
